"""Is f = B / N on the 37-torus with N a product of t_w^{n_w} (as functions) and B in F(2^9) (or F(2^3))?
In base t_1: lambda_f(l) = t_1^{m(l)}; t_w(l) = t_1^{2^{k(w.l)}}.  Need sum_w n_w 2^{k(w.l)} = -m(l) mod 171 (F(2^9))
or mod 12483 (F(2^3)) on every line l where no t_w vanishes.  Solved mod each prime power separately."""
import sys, json, itertools, math
sys.path.insert(0, 'tools'); sys.path.insert(0, 'scratch')
from f18 import *
from sympy import Matrix, GF
from sympy.polys.matrices import DomainMatrix
from sympy.polys.domains import ZZ

T = {t['id']: frozenset(map(tuple, t['terms'])) for t in json.load(open('data/targets.json'))}
lt = log(t(1))
ORD = N18 // math.gcd(lt, N18)  # 87381
assert ORD == 87381
inv = pow(lt // 3, -1, ORD)  # log(t_1) = 3 * (lt//3); base-t exponent of a cube g^l is (l/3) * inv mod ORD

def base_t(v):
    l = log(v)
    if l is None: return None
    assert l % 3 == 0, 'not a cube'
    return (l // 3) * inv % ORD

def k_of(j):
    return log2(j % M)

def directions(R):
    out = []
    for a in range(-R, R + 1):
        for b in range(-R, R + 1):
            if (a, b) > (0, 0) and math.gcd(a, b) == 1:
                out.append((a, b))
    return out

def solve_mod(A, b, p, e):
    """Solve A x = b mod p^e over integers; returns one solution or None (Hensel-free: use Smith-like elimination mod p^e via sympy on Z/p^e? use brute: solve mod p by GF, then lift)."""
    # Simple approach: Gaussian elimination over Z/p^e with unit pivots, fallback to checking consistency.
    n, mcols = len(A), len(A[0])
    mod = p ** e
    M_ = [row[:] + [bb] for row, bb in zip(A, b)]
    M_ = [[x % mod for x in row] for row in M_]
    r = 0
    pivots = []
    for c in range(mcols):
        # find a row >= r with unit entry in column c
        piv = None
        for i in range(r, n):
            if M_[i][c] % p != 0:
                piv = i; break
        if piv is None:
            continue
        M_[r], M_[piv] = M_[piv], M_[r]
        invp = pow(M_[r][c], -1, mod)
        M_[r] = [(x * invp) % mod for x in M_[r]]
        for i in range(n):
            if i != r and M_[i][c]:
                fac = M_[i][c]
                M_[i] = [(x - fac * y) % mod for x, y in zip(M_[i], M_[r])]
        pivots.append(c); r += 1
    # remaining rows: must be consistent. Rows with all coefficient entries divisible by p (non-unit) are not fully reduced; handle crudely
    for i in range(r, n):
        if any(M_[i][c] % mod for c in range(mcols)):
            # non-unit leftover: try to see if divisible structure permits; report as 'unhandled'
            return 'unhandled'
        if M_[i][mcols] % mod:
            return None
    x = [0] * mcols
    for i, c in enumerate(pivots):
        x[c] = M_[i][mcols]
    return x

def search(f, R, modulus_name):
    dirs = directions(R)
    rows, rhs, used = [], [], []
    for l in lines():
        v = value(f, *l)
        if v == 0:
            continue
        if any((w[0]*l[0] + w[1]*l[1]) % M == 0 for w in dirs):
            continue
        m = base_t(v)
        rows.append([pow(2, k_of(w[0]*l[0] + w[1]*l[1]), ORD) for w in dirs])
        rhs.append((-m) % ORD)
        used.append(l)
    res = {}
    for name, (p, e) in {'F(2^9)': [(3, 2), (19, 1)], 'F(2^3)': [(3, 2), (19, 1), (7, 1), (73, 1)]}.items():
        pass
    out = {}
    for p, e in [(3, 2), (19, 1), (7, 1), (73, 1)]:
        out[(p, e)] = solve_mod(rows, rhs, p, e)
    return dirs, used, out

for fid in (4850, 699738, 985232, 1431278, 1968276):
