        summary = {k: ('none' if v is None else v if isinstance(v, str) else 'SOL') for k, v in out.items()}
        print(fid, 'R', R, 'dirs', len(dirs), 'lines used', len(used), summary)
        if out[(3,2)] not in (None, 'unhandled') and out[(19,1)] not in (None, 'unhandled'):
            print('   mod 9:', dict(zip(dirs, out[(3,2)])))
            print('   mod 19:', dict(zip(dirs, out[(19,1)])))
